/** Icon-only button with a 44 dp touch target (or [touch]), a content description for accessibility and a test tag. */
@Composable
fun MlIconButton(
    icon: ImageVector,
    description: String,
    tag: String,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    tint: Color = MlColors.OnSurface,
    touch: Dp = 44.dp,
    iconSize: Dp = 22.dp,
    onClick: () -> Unit,
) {
    Box(
        modifier.size(touch).clickable(enabled = enabled, role = Role.Button, onClick = onClick).testTag(tag).semantics { contentDescription = description },
        contentAlignment = Alignment.Center,
    ) { Icon(icon, contentDescription = null, tint = if (enabled) tint else MlColors.Muted, modifier = Modifier.size(iconSize)) }
}

/** Decorative-or-labelled icon (no click). Pass a [description] when it carries meaning on its own. */
@Composable
fun MlIcon(icon: ImageVector, description: String?, modifier: Modifier = Modifier, tint: Color = MlColors.OnSurface, size: Dp = 20.dp) {
    Icon(icon, contentDescription = description, tint = tint, modifier = modifier.size(size))
}

/** Outlined button that opens a menu: label plus a vector chevron (no text glyph). */
@Composable
fun MenuButton(label: String, tag: String, modifier: Modifier = Modifier, onClick: () -> Unit) {
    androidx.compose.material3.OutlinedButton(onClick = onClick, modifier = modifier.testTag(tag)) {
        androidx.compose.material3.Text(label, maxLines = 1)
        MlIcon(MlIcons.ExpandMore, null, size = 18.dp)
    }
}
